sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;

    // =====================================================
    // DEFAULT STATE
    // =====================================================

    c.currentFilter = "ALL";
    c.searchQuery = "";
    c.successMessage = "";

    // =====================================================
    // AI AUDIT
    // =====================================================

    c.activeAuditItem = null;
    c.isAuditLoading = false;
    c.auditReportContent = "";
    c.parsedAuditSections = [];

    // =====================================================
    // REJECT MODAL
    // =====================================================

    c.rejectModalItem = null;
    c.rejectNotes = "";
    c.isRejecting = false;


    // =====================================================
    // GET COUNT
    // =====================================================

    c.getCount = function(type) {

        var cases = c.data.cases || [];

        if (type === "All") {
            return cases.length;
        }

        var count = 0;

        for (var i = 0; i < cases.length; i++) {

            var caseStatus = String(
                cases[i].status || ""
            ).trim().toLowerCase();

            // Advisor Approved and DSO Approved
            // are both counted as Approved / Completed.
            if (type === "Approved") {

                if (
                    caseStatus === "advisor approved" ||
                    caseStatus === "dso approved" ||
                    caseStatus === "approved"
                ) {
                    count++;
                }

                continue;
            }

            if (
                caseStatus ===
                String(type || "").trim().toLowerCase()
            ) {
                count++;
            }
        }

        return count;
    };

    // =====================================================
    // SET FILTER
    // =====================================================

    c.setFilter = function(filter) {
        c.currentFilter = filter;
    };


    // =====================================================
    // FILTER CASES
    // =====================================================

    c.filterCases = function(item) {

        if (
            c.currentFilter === "Pending" &&
            item.status !== "Pending"
        ) {
            return false;
        }

        if (
            c.currentFilter === "Under Review" &&
            item.status !== "Under Review"
        ) {
            return false;
        }

        if (
            c.currentFilter === "Missing Docs" &&
            item.status !== "Missing Docs"
        ) {
            return false;
        }

        if (
            c.currentFilter === "High" &&
            item.priority !== "High"
        ) {
            return false;
        }


        var search =
            String(c.searchQuery || "")
                .toLowerCase()
                .trim();


        if (!search) {
            return true;
        }


        var searchable =
            (
                (item.case_id || "") + " " +
                (item.student_name || "") + " " +
                (item.student_id || "") + " " +
                (item.visa_type || "") + " " +
                (item.status || "") + " " +
                (item.priority || "")
            ).toLowerCase();


        return searchable.indexOf(search) !== -1;
    };


    // =====================================================
    // VIEW CASE
    // =====================================================

    c.viewCase = function(item) {

        if (!item || !item.sys_id) {

            alert(
                "Unable to open student information. Case ID is missing."
            );

            return;
        }


        $location.search({

            id: "dso_student_info",

            sys_id:
                String(item.sys_id).trim()

        });
    };


    // =====================================================
    // AI AUDIT
    // =====================================================

    c.closeAuditModal = function() {

        c.activeAuditItem = null;
        c.auditReportContent = "";
        c.parsedAuditSections = [];
    };


    c.triggerAiAudit = function(item, advisor) {

        if (!item || !item.sys_id) {
            return;
        }


        c.activeAuditItem = item;
        c.isAuditLoading = true;
        c.auditReportContent = "";
        c.parsedAuditSections = [];


        var ga =
            new GlideAjax(
                "x_snc_visaguardi_0.DSOAiAuditUtil"
            );


        ga.addParam(
            "sysparm_name",
            "generateCaseSummary"
        );


        ga.addParam(
            "sysparm_case_id",
            item.sys_id
        );


        ga.addParam(
            "sysparm_advisor_name",
            advisor ? advisor.name : ""
        );


        ga.addParam(
            "sysparm_advisor_email",
            advisor ? advisor.email : ""
        );


        ga.getXMLAnswer(function(response) {

            c.isAuditLoading = false;

            try {

                var result =
                    JSON.parse(response);


                if (result.success) {

                    c.auditReportContent =
                        result.content || "";


                    c.parsedAuditSections =
                        c.parseMarkdownSections(
                            result.content || ""
                        );

                }
                else {

                    c.auditReportContent =
                        result.error ||
                        "Unable to generate AI Audit Summary.";
                }

            }
            catch (e) {

                console.error(
                    "AI Audit parsing error:",
                    e
                );

                c.auditReportContent =
                    "Error parsing AI response payload.";
            }


            $scope.$applyAsync();

        });
    };


    // =====================================================
    // PARSE AI MARKDOWN
    // =====================================================

    c.parseMarkdownSections = function(text) {

        var sections = [];

        if (!text) {
            return sections;
        }


        var parts =
            text.split(/###\s+/);


        for (
            var i = 1;
            i < parts.length;
            i++
        ) {

            var lines =
                parts[i].split("\n");


            var title =
                lines[0].trim();


            var body =
                lines
                    .slice(1)
                    .join("\n")
                    .trim();


            sections.push({

                title: title,

                body: body

            });
        }


        return sections;
    };


    // =====================================================
    // STATUS HELPERS
    // =====================================================

    c.getStatus = function(item) {

        return String(
            item && item.status
                ? item.status
                : ""
        ).trim().toLowerCase();

    };


    c.isPending = function(item) {

        return c.getStatus(item) === "pending";

    };


    c.isAdvisorApproved = function(item) {

        return c.getStatus(item) ===
            "advisor approved";

    };


    c.isAdvisorRejected = function(item) {

        return c.getStatus(item) ===
            "advisor rejected";

    };


    c.isDsoApproved = function(item) {

        return c.getStatus(item) ===
            "dso approved";

    };


    c.isDsoRejected = function(item) {

        return c.getStatus(item) ===
            "dso rejected";

    };


    // =====================================================
    // CAN SUBMIT PROPER DOCUMENTS
    //
    // Pending           -> YES
    // Advisor Approved  -> NO
    // Advisor Rejected  -> YES
    // DSO Approved      -> NO
    // DSO Rejected      -> NO
    // =====================================================

    c.canSubmitProperDocuments = function(item) {

        if (!item || item.processing) {
            return false;
        }

        if (c.isDsoApproved(item)) {
            return false;
        }

        if (c.isDsoRejected(item)) {
            return false;
        }

        if (c.isPending(item)) {
            return true;
        }

        if (c.isAdvisorRejected(item)) {
            return true;
        }

        return false;

    };


    // =====================================================
    // CAN APPROVE
    //
    // Pending           -> YES
    // Advisor Approved  -> NO
    // Advisor Rejected  -> YES
    // DSO Approved      -> NO
    // DSO Rejected      -> NO
    // =====================================================

    c.canApprove = function(item) {

        if (!item || item.processing) {
            return false;
        }

        if (c.isDsoApproved(item)) {
            return false;
        }

        if (c.isDsoRejected(item)) {
            return false;
        }

        if (c.isPending(item)) {
            return true;
        }

        if (c.isAdvisorApproved(item)) {
            return false;
        }

        if (c.isAdvisorRejected(item)) {
            return true;
        }

        return false;

    };


    // =====================================================
    // CAN REJECT
    //
    // Pending           -> YES
    // Advisor Approved  -> YES
    // Advisor Rejected  -> YES
    // DSO Approved      -> NO
    // DSO Rejected      -> NO
    // =====================================================

    c.canReject = function(item) {

        if (!item || item.processing) {
            return false;
        }

        if (c.isDsoApproved(item)) {
            return false;
        }

        if (c.isDsoRejected(item)) {
            return false;
        }

        if (c.isPending(item)) {
            return true;
        }

        return (
            c.isAdvisorApproved(item) ||
            c.isAdvisorRejected(item)
        );

    };


    // =====================================================
    // APPROVE CASE
    // =====================================================

    c.approveCase = function(item) {

        if (!c.canApprove(item)) {
            return;
        }


        var confirmed =
            window.confirm(
                "Are you sure you want to approve case " +
                item.case_id +
                "?"
            );


        if (!confirmed) {
            return;
        }


        item.processing = true;
        c.successMessage = "";


        c.server.get({

            action: "approve",

            case_sys_id:
                item.sys_id

        }).then(

            function(response) {

                item.processing = false;


                if (
                    response.data &&
                    response.data.success
                ) {

                    item.status =
                        response.data.statusSet ||
                        "DSO Approved";


                    c.successMessage =
                        "Case " +
                        item.case_id +
                        " approved successfully.";

                }
                else {

                    alert(
                        (
                            response.data &&
                            response.data.error
                        ) ||
                        "Unable to approve the case."
                    );
                }

            },

            function() {

                item.processing = false;

                alert(
                    "Server error while approving the case."
                );
            }
        );
    };


    // =====================================================
    // OPEN REJECT MODAL
    // =====================================================

    c.openRejectModal = function(item) {

        if (!c.canReject(item)) {
            return;
        }


        c.rejectModalItem = item;
        c.rejectNotes = "";
        c.isRejecting = false;
    };


    // =====================================================
    // CLOSE REJECT MODAL
    // =====================================================

    c.closeRejectModal = function() {

        if (c.isRejecting) {
            return;
        }


        c.rejectModalItem = null;
        c.rejectNotes = "";
    };


    // =====================================================
    // CONFIRM REJECT
    // =====================================================

    c.confirmRejectCase = function() {

        var item =
            c.rejectModalItem;


        if (!item || !item.sys_id) {
            return;
        }


        var notes =
            String(
                c.rejectNotes || ""
            ).trim();


        if (!notes) {

            alert(
                "Close Notes are required when rejecting a case."
            );

            return;
        }


        if (c.isRejecting) {
            return;
        }


        c.isRejecting = true;
        item.processing = true;


        c.server.get({

            action: "reject",

            case_sys_id:
                item.sys_id,

            close_notes:
                notes

        }).then(

            function(response) {

                item.processing = false;
                c.isRejecting = false;


                if (
                    response.data &&
                    response.data.success
                ) {

                    item.status =
                        response.data.statusSet ||
                        "DSO Rejected";


                    item.close_notes =
                        response.data.closeNotes ||
                        notes;


                    c.successMessage =
                        "Case " +
                        item.case_id +
                        " rejected successfully.";


                    c.rejectModalItem = null;
                    c.rejectNotes = "";

                }
                else {

                    alert(
                        (
                            response.data &&
                            response.data.error
                        ) ||
                        "Unable to reject the case."
                    );
                }

            },

            function() {

                item.processing = false;
                c.isRejecting = false;


                alert(
                    "Server error while rejecting the case."
                );
            }
        );
    };


    // =====================================================
    // SUBMIT PROPER DOCUMENTS
    // =====================================================

    c.submitProperDocuments = function(item) {

        if (!c.canSubmitProperDocuments(item)) {
            return;
        }


        var confirmed =
            window.confirm(
                "Send a request to the student to submit the proper documents for case " +
                item.case_id +
                "?"
            );


        if (!confirmed) {
            return;
        }


        item.processing = true;
        c.successMessage = "";


        c.server.get({

            action:
                "request_documents",

            case_sys_id:
                item.sys_id

        }).then(

            function(response) {

                item.processing = false;


                if (
                    response.data &&
                    response.data.success
                ) {

                    item.status =
                        response.data.statusSet ||
                        "Missing Docs";


                    c.successMessage =
                        "Proper document submission requested for case " +
                        item.case_id +
                        ".";

                }
                else {

                    alert(
                        (
                            response.data &&
                            response.data.error
                        ) ||
                        "Unable to request proper documents."
                    );
                }

            },

            function() {

                item.processing = false;

                alert(
                    "Server error while requesting documents."
                );
            }
        );
    };


    // =====================================================
    // CLEANUP
    // =====================================================

    $scope.$on(
        "$destroy",
        function() {}
    );

};

sp_widget.css:
/* =========================================================
   VISA GUARDIAN AI
   MY & ALL VISA CASES
   ENTERPRISE UI THEME
   ========================================================= */

.vg-workspace-container {
    width: 100%;
    min-height: 100vh;

    padding: 0;
    margin: 0;

    box-sizing: border-box;

    background:
        linear-gradient(
            180deg,
            #f5f8fd 0%,
            #f1f5fa 100%
        );

    color: #173f6d;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Helvetica,
        Arial,
        sans-serif;

    -webkit-font-smoothing: antialiased;
}


/* =========================================================
   GLOBAL
   ========================================================= */

.vg-workspace-container *,
.vg-workspace-container *::before,
.vg-workspace-container *::after {
    box-sizing: border-box;
}


/* =========================================================
   HERO BANNER
   ========================================================= */

.vg-hero-banner {
    position: relative;

    width: 100%;
    min-height: 145px;

    padding: 28px 40px;

    margin-bottom: 26px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    overflow: hidden;

    background:
        linear-gradient(
            135deg,
            #0a2345 0%,
            #123f76 55%,
            #2468b5 100%
        );

    border-radius: 17px;

    color: #ffffff;

    box-shadow:
        0 12px 30px
        rgba(9, 39, 75, .16);
}


/* Decorative hero glow */

.vg-hero-banner::before {
    content: "";

    position: absolute;

    width: 300px;
    height: 300px;

    right: -120px;
    top: -145px;

    border-radius: 50%;

    background:
        rgba(255,255,255,.055);

    pointer-events: none;
}


.vg-hero-banner::after {
    content: "";

    position: absolute;

    width: 180px;
    height: 180px;

    right: 17%;
    bottom: -150px;

    border-radius: 50%;

    background:
        rgba(80,160,255,.07);

    pointer-events: none;
}


/* Hero content */

.hero-content {
    position: relative;

    z-index: 2;

    display: flex;

    align-items: center;

    gap: 20px;
}


/* Hero icon */

.hero-icon {
    width: 62px;
    height: 62px;

    min-width: 62px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 16px;

    background:
        rgba(255,255,255,.12);

    border:
        1px solid
        rgba(255,255,255,.20);

    color: #ffffff;

    font-size: 25px;

    box-shadow:
        inset 0 1px 0
        rgba(255,255,255,.08);
}


/* Hero heading */

.hero-text h2 {
    margin: 0 0 7px;

    color: #ffffff;

    font-size: 27px;

    line-height: 1.2;

    font-weight: 750;

    letter-spacing: -.4px;
}


.hero-text p {
    margin: 0;

    color:
        rgba(255,255,255,.78);

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   METRIC ROW
   ========================================================= */

.metric-row {
    margin-left: -10px;
    margin-right: -10px;

    margin-bottom: 5px;
}


.metric-row > [class*="col-"] {
    padding-left: 10px;
    padding-right: 10px;

    margin-bottom: 20px;
}


/* =========================================================
   METRIC CARDS
   ========================================================= */

.vg-metric-card {
    position: relative;

    min-height: 112px;

    padding: 20px 23px;

    display: flex;

    align-items: center;

    gap: 17px;

    overflow: hidden;

    background: #ffffff;

    border:
        1px solid
        #e0e8f1;

    border-radius: 15px;

    box-shadow:
        0 6px 18px
        rgba(32,65,101,.055);

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}


.vg-metric-card:hover {
    transform:
        translateY(-3px);

    border-color:
        #d2dfed;

    box-shadow:
        0 12px 28px
        rgba(32,65,101,.10);
}


/* Decorative circle */

.vg-metric-card::after {
    content: "";

    position: absolute;

    width: 105px;
    height: 105px;

    right: -48px;
    bottom: -55px;

    border-radius: 50%;

    background:
        rgba(37,99,235,.025);

    pointer-events: none;
}


/* Metric icon */

.metric-icon {
    width: 54px;
    height: 54px;

    min-width: 54px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 15px;

    font-size: 21px;
}


.blue-circle {
    background: #eaf2ff;
    color: #2563eb;
}


.orange-circle {
    background: #fff4e5;
    color: #e58b18;
}


.green-circle {
    background: #e9f8ef;
    color: #0aa66b;
}


.red-circle {
    background: #feecee;
    color: #dc3d4c;
}


/* Metric content */

.metric-data {
    display: flex;
    flex-direction: column;

    position: relative;

    z-index: 2;
}


.metric-number {
    font-size: 27px;

    line-height: 30px;

    font-weight: 800;

    letter-spacing: -.3px;
}


.metric-label {
    margin-top: 5px;

    color: #8293aa;

    font-size: 10px;

    line-height: 15px;

    font-weight: 800;

    letter-spacing: .7px;

    text-transform: uppercase;
}


.metric-subtext {
    margin-top: 2px;

    font-size: 11px;

    line-height: 16px;

    font-weight: 600;
}


/* Metric colors */

.text-blue {
    color: #2563eb !important;
}


.text-orange {
    color: #df850e !important;
}


.text-red {
    color: #dc3d4c !important;
}


.text-green {
    color: #0aa66b !important;
}


/* =========================================================
   MAIN CASE CARD
   ========================================================= */

.vg-card {
    width: 100%;

    padding: 27px 28px;

    margin-bottom: 22px;

    background: #ffffff;

    border:
        1px solid
        #dfe7f0;

    border-radius: 17px;

    box-shadow:
        0 7px 22px
        rgba(32,65,101,.055);
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.vg-card-header {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 18px;

    padding-bottom: 20px;

    margin-bottom: 15px;

    border-bottom:
        1px solid
        #e8edf4;
}


.header-left {
    display: flex;

    align-items: center;

    gap: 12px;

    min-width: 220px;
}


.header-left h4 {
    margin: 0;

    color: #173f6d;

    font-size: 19px;

    line-height: 1.25;

    font-weight: 750;
}


.header-left h4 i {
    margin-right: 8px;

    color: #2563eb;
}


/* Case count */

.case-count-label {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-width: 70px;

    padding: 8px 13px;

    border-radius: 20px;

    background:
        #eaf2ff;

    color:
        #2563eb;

    font-size: 11px;

    font-weight: 800;

    line-height: 1.2;
}


/* =========================================================
   FILTER AREA
   ========================================================= */

.header-right {
    display: flex;

    align-items: center;

    justify-content: flex-end;

    gap: 13px;

    min-width: 0;
}


/* Filter container */

.filter-pills {
    display: flex;

    align-items: center;

    padding: 4px;

    gap: 2px;

    background:
        #f4f7fb;

    border:
        1px solid
        #e6ebf2;

    border-radius:
        11px;
}


/* Filter buttons */

.filter-btn {
    min-height: 38px;

    padding: 7px 14px;

    border: none;

    border-radius: 8px;

    background: transparent;

    color: #8091a8;

    font-size: 12px;

    font-weight: 650;

    cursor: pointer;

    transition:
        all .18s ease;
}


.filter-btn:hover {
    color: #2563eb;

    background:
        #ffffff;
}


.filter-btn.active {
    color: #2563eb;

    background:
        #ffffff;

    box-shadow:
        0 2px 8px
        rgba(25,55,90,.08);
}


/* =========================================================
   SEARCH
   ========================================================= */

.search-wrapper {
    position: relative;

    width: 270px;
}


.search-icon {
    position: absolute;

    left: 14px;
    top: 50%;

    transform:
        translateY(-50%);

    color:
        #8b9bb1;

    font-size:
        13px;

    pointer-events:
        none;
}


.search-input {
    width: 100%;

    height: 42px;

    padding:
        8px 13px 8px 38px;

    border:
        1px solid
        #dce5ef;

    border-radius:
        10px;

    background:
        #f8fafc;

    color:
        #1b3157;

    font-size:
        12px;

    outline:
        none;

    transition:
        all .2s ease;
}


.search-input::placeholder {
    color:
        #9aa9bc;
}


.search-input:focus {
    background:
        #ffffff;

    border-color:
        #2563eb;

    box-shadow:
        0 0 0 3px
        rgba(37,99,235,.09);
}


/* =========================================================
   TABLE WRAPPER
   ========================================================= */

.table-responsive {
    width: 100%;

    overflow-x: auto;

    overflow-y: hidden;

    border-radius: 10px;
}


/* =========================================================
   CASE TABLE
   ========================================================= */

.vg-table {
    width: 100%;

    min-width: 1180px;

    margin: 0;

    border-collapse:
        separate;

    border-spacing:
        0;
}


/* Table header */

.vg-table thead th {
    padding:
        14px 15px;

    background:
        #f7f9fc;

    border-bottom:
        1px solid
        #e2e9f1;

    color:
        #7e90a8;

    font-size:
        10px;

    font-weight:
        800;

    letter-spacing:
        .65px;

    text-transform:
        uppercase;

    white-space:
        nowrap;
}


.vg-table thead th:first-child {
    border-radius:
        10px 0 0 10px;
}


.vg-table thead th:last-child {
    border-radius:
        0 10px 10px 0;
}


/* Table rows */

.vg-table tbody tr {
    transition:
        background .18s ease;
}


.vg-table tbody tr:hover {
    background:
        #f8fbff;
}


/* Table cells */

.vg-table tbody td {
    padding:
        17px 15px;

    border-bottom:
        1px solid
        #edf1f5;

    color:
        #344f70;

