sp_widget.script:
(function() {

    // =====================================================
    // DEFAULT DATA
    // =====================================================

    data.cases = [];

    data.error = "";

    data.success = false;

    data.message = "";

    data.caseDetails = null;

    // =====================================================
    // APPROVED / COMPLETED COUNTERS
    // =====================================================

    data.approved_cases = 0;
    data.completed_cases = 0;



    // =====================================================
    // CURRENT USER
    // =====================================================

    var currentUser =
        gs.getUser();


    // =====================================================
    // CURRENT ADVISOR / USER INFORMATION
    // =====================================================

    var advisorGr =
        new GlideRecord("sys_user");


    if (advisorGr.get(gs.getUserID())) {

        data.currentAdvisor = {

            name:
                advisorGr.getValue("name") || "",

            email:
                advisorGr.getValue("email") || ""

        };
    }


    // =====================================================
    // RUN DSO AI AUDIT ACTION
    // =====================================================

    if (
        input &&
        input.action === "run_dso_audit"
    ) {

        var auditCaseSysId =
            String(
                input.case_sys_id || ""
            ).trim();


        var advName =
            String(
                input.advisor_name || ""
            ).trim();


        var advEmail =
            String(
                input.advisor_email || ""
            ).trim();


        if (!auditCaseSysId) {

            data.success = false;

            data.error =
                "Case ID is missing for audit.";

            return;
        }


        var auditCaseGr =
            new GlideRecord(
                "x_snc_visaguardi_0_visa_case"
            );


        if (
            auditCaseGr.get(
                auditCaseSysId
            )
        ) {

            var caseNum =
                auditCaseGr.getDisplayValue(
                    "number"
                ) ||
                auditCaseSysId;


            var auditLog =
                new GlideRecord(
                    "x_snc_visaguardi_0_ai_audit_cases"
                );


            if (auditLog.isValid()) {

                auditLog.initialize();


                auditLog.setValue(
                    "case_id",
                    caseNum
                );


                auditLog.setValue(
                    "advisor_name",
                    advName
                );


                auditLog.setValue(
                    "advisor_email",
                    advEmail
                );


                auditLog.setValue(
                    "audit_timestamp",
                    new GlideDateTime()
                );


                auditLog.insert();
            }


            data.success = true;

            data.message =
                "AI Audit logged successfully.";

            return;

        } else {

            data.success = false;

            data.error =
                "Visa case not found for audit execution.";

            return;
        }
    }


    // =====================================================
    // VIEW CASE INFORMATION
    // =====================================================

    if (
        input &&
        input.action === "view"
    ) {

        var viewCaseSysId =
            String(
                input.case_sys_id || ""
            ).trim();


        if (!viewCaseSysId) {

            data.success = false;

            data.error =
                "Case ID is missing.";

            return;
        }


        var viewCase =
            new GlideRecord(
                "x_snc_visaguardi_0_visa_case"
            );


        if (!viewCase.isValid()) {

            data.success = false;

            data.error =
                "Visa Case table could not be found.";

            return;
        }


        if (
            !viewCase.get(
                viewCaseSysId
            )
        ) {

            data.success = false;

            data.error =
                "Visa case could not be found.";

            return;
        }


        var details = {};


        details.sys_id =
            viewCase.getUniqueValue();


        // =================================================
        // CASE DETAILS
        // =================================================

        details.case = {};


        details.case.case_id =
            viewCase.getUniqueValue();


        if (
            viewCase.isValidField("number") &&
            viewCase.getValue("number")
        ) {

            details.case.case_id =
                viewCase.getDisplayValue(
                    "number"
                );
        }


        if (
            viewCase.isValidField("case_type")
        ) {

            details.case.case_type =
                viewCase.getDisplayValue(
                    "case_type"
                );

        } else {

            details.case.case_type =
                "Visa Case";
        }


        if (
            viewCase.isValidField("case_stage")
        ) {

            details.case.case_stage =
                viewCase.getDisplayValue(
                    "case_stage"
                );

        } else {

            details.case.case_stage =
                "N/A";
        }


        if (
            viewCase.isValidField("priority")
        ) {

            details.case.priority =
                viewCase.getDisplayValue(
                    "priority"
                );

        } else {

            details.case.priority =
                "N/A";
        }


        if (
            viewCase.isValidField("description")
        ) {

            details.case.description =
                viewCase.getDisplayValue(
                    "description"
                );

        } else {

            details.case.description = "";
        }


        if (
            viewCase.isValidField("sys_created_on")
        ) {

            details.case.created_on =
                viewCase.getDisplayValue(
                    "sys_created_on"
                );

        } else {

            details.case.created_on = "";
        }


        if (
            viewCase.isValidField("sys_updated_on")
        ) {

            details.case.updated_on =
                viewCase.getDisplayValue(
                    "sys_updated_on"
                );

        } else {

            details.case.updated_on = "";
        }


        // =================================================
        // VISA CATEGORY
        // =================================================

        details.case.visa_category =
            "N/A";


        if (
            viewCase.isValidField("visa_category") &&
            viewCase.getValue("visa_category")
        ) {

            details.case.visa_category =
                viewCase.getDisplayValue(
                    "visa_category"
                );
        }


        if (
            details.case.visa_category === "N/A" &&
            viewCase.isValidField("visa_type") &&
            viewCase.getValue("visa_type")
        ) {

            details.case.visa_category =
                viewCase.getDisplayValue(
                    "visa_type"
                );
        }


        // =================================================
        // STUDENT
        // =================================================

        details.student = {

            name:
                "Unknown Student",

            student_id:
                "",

            email:
                "",

            mobile_phone:
                "",

            university_name:
                "",

            degree_program:
                "",

            user_name:
                ""
        };


        var studentSysId = "";


        if (
            viewCase.isValidField("student") &&
            viewCase.getValue("student")
        ) {

            studentSysId =
                viewCase.getValue("student");
        }


        // =================================================
        // STUDENT PROFILE
        // =================================================

        if (studentSysId) {

            var studentGR =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );


            if (
                studentGR.isValid() &&
                studentGR.get(studentSysId)
            ) {

                details.student.name =
                    studentGR.getDisplayValue();


                if (
                    studentGR.isValidField("user_name")
                ) {

                    details.student.user_name =
                        studentGR.getValue(
                            "user_name"
                        );
                }


                if (
                    studentGR.isValidField("student_id") &&
                    studentGR.getValue("student_id")
                ) {

                    details.student.student_id =
                        studentGR.getValue(
                            "student_id"
                        );

                } else if (
                    studentGR.isValidField("roll_number") &&
                    studentGR.getValue("roll_number")
                ) {

                    details.student.student_id =
                        studentGR.getValue(
                            "roll_number"
                        );

                } else if (
                    studentGR.isValidField("user_name") &&
                    studentGR.getValue("user_name")
                ) {

                    details.student.student_id =
                        studentGR.getValue(
                            "user_name"
                        );
                }


                if (
                    studentGR.isValidField("email")
                ) {

                    details.student.email =
                        studentGR.getValue(
                            "email"
                        );
                }


                if (
                    studentGR.isValidField("mobile_phone")
                ) {

                    details.student.mobile_phone =
                        studentGR.getValue(
                            "mobile_phone"
                        );
                }


                if (
                    studentGR.isValidField("university_name")
                ) {

                    details.student.university_name =
                        studentGR.getDisplayValue(
                            "university_name"
                        );
                }


                if (
                    studentGR.isValidField("degree_program")
                ) {

                    details.student.degree_program =
                        studentGR.getDisplayValue(
                            "degree_program"
                        );
                }


                // =========================================
                // VISA
                // =========================================

                details.visa = {

                    current_visa_status:
                        "N/A",

                    visa_type:
                        "N/A",

                    sevis_id:
                        "N/A",

                    visa_expiry_date:
                        "N/A",

                    passport_expiry_date:
                        "N/A"
                };


                if (
                    studentGR.isValidField(
                        "current_visa_status"
                    )
                ) {

                    details.visa.current_visa_status =
                        studentGR.getDisplayValue(
                            "current_visa_status"
                        );
                }


                if (
                    studentGR.isValidField(
                        "visa_type"
                    )
                ) {

                    details.visa.visa_type =
                        studentGR.getDisplayValue(
                            "visa_type"
                        );
                }


                if (
                    studentGR.isValidField(
                        "sevis_id"
                    )
                ) {

                    details.visa.sevis_id =
                        studentGR.getValue(
                            "sevis_id"
                        );
                }


                if (
                    studentGR.isValidField(
                        "visa_expiry_date"
                    )
                ) {

                    details.visa.visa_expiry_date =
                        studentGR.getDisplayValue(
                            "visa_expiry_date"
                        );
                }


                if (
                    studentGR.isValidField(
                        "passport_expiry_date"
                    )
                ) {

                    details.visa.passport_expiry_date =
                        studentGR.getDisplayValue(
                            "passport_expiry_date"
                        );
                }
            }
        }


        // =================================================
        // VISA FALLBACK
        // =================================================

        if (!details.visa) {

            details.visa = {

                current_visa_status:
                    "N/A",

                visa_type:
                    details.case.visa_category,

                sevis_id:
                    "N/A",

                visa_expiry_date:
                    "N/A",

                passport_expiry_date:
                    "N/A"
            };
        }


        // =================================================
        // DOCUMENTS
        // =================================================

        details.documents = [];


        // -------------------------------------------------
        // CASE ATTACHMENTS
        // -------------------------------------------------

        var caseAttachments =
            new GlideRecord(
                "sys_attachment"
            );


        caseAttachments.addQuery(
            "table_name",
            "x_snc_visaguardi_0_visa_case"
        );


        caseAttachments.addQuery(
            "table_sys_id",
            viewCaseSysId
        );


        caseAttachments.orderByDesc(
            "sys_created_on"
        );


        caseAttachments.query();


        while (
            caseAttachments.next()
        ) {

            var caseDoc = {};


            caseDoc.sys_id =
                caseAttachments.getUniqueValue();


            caseDoc.file_name =
                caseAttachments.getValue(
                    "file_name"
                );


            caseDoc.content_type =
                caseAttachments.getValue(
                    "content_type"
                );


            caseDoc.size_bytes =
                caseAttachments.getValue(
                    "size_bytes"
                );


            caseDoc.created_on =
                caseAttachments.getDisplayValue(
                    "sys_created_on"
                );


            caseDoc.source =
                "Visa Case";


            details.documents.push(
                caseDoc
            );
        }


        // -------------------------------------------------
        // STUDENT PROFILE ATTACHMENTS
        // -------------------------------------------------

        if (studentSysId) {

            var studentAttachments =
                new GlideRecord(
                    "sys_attachment"
                );


            studentAttachments.addQuery(
                "table_name",
                "x_snc_visaguardi_0_student_profile"
            );


            studentAttachments.addQuery(
                "table_sys_id",
                studentSysId
            );


            studentAttachments.orderByDesc(
                "sys_created_on"
            );


            studentAttachments.query();


            while (
                studentAttachments.next()
            ) {

                var studentDoc = {};


                studentDoc.sys_id =
                    studentAttachments.getUniqueValue();


                studentDoc.file_name =
                    studentAttachments.getValue(
                        "file_name"
                    );


                studentDoc.content_type =
                    studentAttachments.getValue(
                        "content_type"
                    );


                studentDoc.size_bytes =
                    studentAttachments.getValue(
                        "size_bytes"
                    );


                studentDoc.created_on =
                    studentAttachments.getDisplayValue(
                        "sys_created_on"
                    );


                studentDoc.source =
                    "Student Profile";


                details.documents.push(
                    studentDoc
                );
            }
        }


        data.caseDetails =
            details;


        data.success =
            true;


        data.message =
            "Case information loaded successfully.";


        return;
    }


    // =====================================================
    // CASE ACTIONS
    // =====================================================

    if (
        input &&
        input.action
    ) {

        var action =
            String(
                input.action || ""
            ).trim();


        var caseSysId =
            String(
                input.case_sys_id || ""
            ).trim();


        // -------------------------------------------------
        // VALIDATE CASE ID
        // -------------------------------------------------

        if (!caseSysId) {

            data.success = false;

            data.error =
                "Case ID is missing.";

            return;
        }


        // -------------------------------------------------
        // GET CASE
        // -------------------------------------------------

        var actionCase =
            new GlideRecord(
                "x_snc_visaguardi_0_visa_case"
            );


        if (!actionCase.isValid()) {

            data.success = false;

            data.error =
                "Visa Case table could not be found.";

            return;
        }


        if (
            !actionCase.get(caseSysId)
        ) {

            data.success = false;

            data.error =
                "Visa case could not be found.";

            return;
        }


        // -------------------------------------------------
        // DSO ROLE CHECK
        // -------------------------------------------------

        if (
            !currentUser.hasRole("dso")
        ) {

            data.success = false;

            data.error =
                "Only a DSO can perform this action.";

            return;
        }


        // -------------------------------------------------
        // CASE STAGE
        // -------------------------------------------------

        var currentStage = "";


        if (
            actionCase.isValidField(
                "case_stage"
            )
        ) {

            currentStage =
                actionCase.getDisplayValue(
                    "case_stage"
                ) || "";
        }


        // =================================================
        // APPROVE
        // =================================================

        if (
            action === "approve"
        ) {

            /*
             * Advisor Approved:
             * DSO cannot approve.
             */

            if (
                currentStage ===
                "Advisor Approved"
            ) {

                data.success = false;

                data.error =
                    "This case was already approved by the advisor. Request proper documents or reject the case instead.";

                return;
            }


            /*
             * Already DSO Approved
             */

            if (
                currentStage ===
                "DSO Approved"
            ) {

                data.success = false;

                data.error =
                    "This case is already DSO Approved.";

                return;
            }


            /*
             * Already DSO Rejected
             */

            if (
                currentStage ===
                "DSO Rejected"
            ) {

                data.success = false;

                data.error =
                    "A DSO Rejected case cannot be approved.";

                return;
            }


            if (
                !actionCase.isValidField(
                    "case_stage"
                )
            ) {

                data.success = false;

                data.error =
                    "Case Stage field was not found.";

                return;
            }


            actionCase.setValue(
                "case_stage",
                "DSO Approved"
            );


            var approveResult =
                actionCase.update();


            if (!approveResult) {

                data.success = false;

                data.error =
                    "Unable to approve the case.";

                return;
            }


            data.success = true;

            data.statusSet =
                "DSO Approved";

            data.message =
                "Case approved successfully.";

            return;
        }


        // =================================================
        // REJECT
        // =================================================

        if (
            action === "reject"
        ) {

            /*
             * DSO Approved cannot be rejected.
             */

            if (
                currentStage ===
                "DSO Approved"
            ) {

                data.success = false;

                data.error =
                    "A DSO Approved case cannot be rejected.";

                return;
            }


            /*
             * Already rejected
             */

            if (
                currentStage ===
                "DSO Rejected"
            ) {

                data.success = false;

                data.error =
                    "This case is already DSO Rejected.";

                return;
            }


            // ---------------------------------------------
            // CLOSE NOTES
            // ---------------------------------------------

            var closeNotes =
                String(
                    input.close_notes || ""
                ).trim();


            if (!closeNotes) {

                data.success = false;

                data.error =
                    "Close Notes are required when rejecting a case.";

                return;
            }


            if (
                !actionCase.isValidField(
                    "case_stage"
                )
            ) {

                data.success = false;

                data.error =
                    "Case Stage field was not found.";

                return;
            }


            // ---------------------------------------------
            // SET DSO REJECTED
            // ---------------------------------------------

            actionCase.setValue(
                "case_stage",
                "DSO Rejected"
            );


            // ---------------------------------------------
            // SAVE CLOSE NOTES
            // ---------------------------------------------

            if (
                actionCase.isValidField(
                    "close_notes"
                )
            ) {

                actionCase.setValue(
                    "close_notes",
                    closeNotes
                );

            } else if (
                actionCase.isValidField(
                    "comments"
                )
            ) {

                actionCase.setValue(
                    "comments",
                    "DSO Rejection Notes:\n\n" +
                    closeNotes
                );

            } else if (
                actionCase.isValidField(
                    "description"
                )
            ) {

                var existingDescription =
                    actionCase.getValue(
                        "description"
                    ) || "";


                actionCase.setValue(
                    "description",

                    existingDescription +
                    "\n\nDSO Rejection Notes:\n" +
                    closeNotes
                );
            }


            var rejectResult =
                actionCase.update();


            if (!rejectResult) {

                data.success = false;

                data.error =
                    "Unable to reject the case.";

                return;
            }


            data.success = true;

            data.statusSet =
                "DSO Rejected";

            data.closeNotes =
                closeNotes;

            data.message =
                "Case rejected successfully.";

            return;
        }


        // =================================================
        // REQUEST PROPER DOCUMENTS
        // =================================================

        if (
            action ===
            "request_documents"
        ) {

            /*
             * Allowed only after advisor decision.
             */

            if (
                currentStage !==
                    "Pending" &&
                currentStage !==
                    "Advisor Approved" &&
                currentStage !==
                    "Advisor Rejected"
            ) {

                data.success = false;

                data.error =
                    "Proper document submission cannot be requested for the current case status.";

                return;
            }


            if (
                !actionCase.isValidField(
                    "case_stage"
                )
            ) {

                data.success = false;

                data.error =
                    "Case Stage field was not found.";

                return;
            }


            // ---------------------------------------------
            // SET MISSING DOCS
            // ---------------------------------------------

            actionCase.setValue(
                "case_stage",
                "Missing Docs"
            );


            // ---------------------------------------------
            // INTERNAL NOTE
            // ---------------------------------------------

            var documentNote =
                "DSO requested the student to submit the proper/correct documents.";


            if (
                actionCase.isValidField(
                    "comments"
                )
            ) {

                actionCase.setValue(
                    "comments",
                    documentNote
                );
            }


            var documentResult =
                actionCase.update();


            if (!documentResult) {

                data.success = false;

                data.error =
                    "Unable to request proper documents.";

                return;
            }


            data.success = true;

            data.statusSet =
                "Missing Docs";

            data.message =
                "Proper document submission requested successfully.";

            return;
        }


        // =================================================
        // INVALID ACTION
        // =================================================

        data.success = false;

        data.error =
            "Invalid case action.";

        return;
    }


    // =====================================================
    // LOAD ALL VISA CASES
    // =====================================================

    var gr =
        new GlideRecord(
            "x_snc_visaguardi_0_visa_case"
        );


    if (!gr.isValid()) {

        data.error =
            "Visa Case table could not be found.";

        return;
    }


    if (
        gr.isValidField(
            "sys_created_on"
        )
    ) {

        gr.orderByDesc(
            "sys_created_on"
        );
    }


    gr.query();


    while (gr.next()) {

        var item = {};


        // =================================================
        // CASE ID
        // =================================================

        item.sys_id =
            gr.getUniqueValue();


        item.case_id =
            gr.getUniqueValue();


        if (
            gr.isValidField("number") &&
            gr.getValue("number")
        ) {

            item.case_id =
                gr.getDisplayValue(
                    "number"
                );
        }


        // =================================================
        // STUDENT
        // =================================================

        item.student_name =
            "Unknown Student";


        item.student_id =
            "";


        if (
            gr.isValidField("student") &&
            gr.getValue("student")
        ) {

            item.student_name =
                gr.getDisplayValue(
                    "student"
                );


            var studentSysIdList =
                gr.getValue(
                    "student"
                );


            var studentGRList =
                new GlideRecord(
                    "x_snc_visaguardi_0_student_profile"
                );


            if (
                studentGRList.isValid() &&
                studentGRList.get(
                    studentSysIdList
                )
            ) {

                if (
                    studentGRList.isValidField(
                        "user_name"
                    ) &&
                    studentGRList.getValue(
                        "user_name"
                    )
                ) {

                    item.student_id =
                        studentGRList.getValue(
                            "user_name"
                        );

                } else if (
                    studentGRList.isValidField(
                        "student_id"
                    ) &&
                    studentGRList.getValue(
                        "student_id"
                    )
                ) {

                    item.student_id =
                        studentGRList.getValue(
                            "student_id"
                        );

                } else if (
                    studentGRList.isValidField(
                        "roll_number"
                    ) &&
                    studentGRList.getValue(
                        "roll_number"
                    )
                ) {

                    item.student_id =
                        studentGRList.getValue(
                            "roll_number"
                        );
                }
            }
        }


        // =================================================
        // VISA TYPE
        // =================================================

        item.visa_type =
            "Visa Service";


        if (
            gr.isValidField("case_type") &&
            gr.getValue("case_type")
        ) {

            item.visa_type =
                gr.getDisplayValue(
                    "case_type"
                );
        }


        // =================================================
        // STATUS
        // =================================================

        var rawStatus =
            gr.getDisplayValue(
                "case_stage"
            ) || "";

        // =================================================
        // APPROVED / COMPLETED COUNT
        // =================================================
        // Advisor Approved OR DSO Approved = approved.
        // Each case is counted only once.
        // =================================================

        var stageText = String(
            rawStatus || ""
        ).trim().toLowerCase();

        var advisorDecisionText = "";

        if (gr.isValidField("advisor_decision")) {
            advisorDecisionText = String(
                gr.getDisplayValue("advisor_decision") ||
                gr.getValue("advisor_decision") ||
                ""
            ).trim().toLowerCase();
        }

        var statusText = "";

        if (gr.isValidField("status")) {
            statusText = String(
                gr.getDisplayValue("status") ||
                gr.getValue("status") ||
                ""
            ).trim().toLowerCase();
        }

        var isApprovedCase =
            stageText === "advisor approved" ||
            stageText === "dso approved" ||
            stageText === "approved" ||
            statusText === "advisor approved" ||
            statusText === "dso approved" ||
            statusText === "approved" ||
            advisorDecisionText === "approved";

        if (isApprovedCase) {
            data.approved_cases++;
            data.completed_cases++;
        }



        /*
         * Preserve the exact important statuses.
         */

        if (

            rawStatus ===
                "Advisor Approved" ||

            rawStatus ===
                "DSO Approved" ||

            rawStatus ===
                "Advisor Rejected" ||

            rawStatus ===
                "DSO Rejected"

        ) {

            item.status =
                rawStatus;

        } else {

            var status =
                String(
                    rawStatus
                ).toLowerCase();


            if (
                status.indexOf(
                    "submitted"
                ) !== -1 ||

                status.indexOf(
                    "pending"
                ) !== -1
            ) {

                item.status =
                    "Pending";

            } else if (
                status.indexOf(
                    "review"
                ) !== -1
            ) {

                item.status =
                    "Under Review";

            } else if (
                status.indexOf(
                    "missing"
                ) !== -1
            ) {

                item.status =
                    "Missing Docs";

            } else if (
                status.indexOf(
                    "approv"
                ) !== -1
            ) {

                item.status =
                    "Approved";

            } else if (
                status.indexOf(
                    "reject"
                ) !== -1
            ) {

                item.status =
                    "Rejected";

            } else {

                item.status =
                    rawStatus ||
                    "Pending";
            }
        }


        // =================================================
        // PRIORITY
        // =================================================

        item.priority =
            "Low";


        if (
            gr.isValidField("priority") &&
            gr.getValue("priority")
        ) {

            var priorityValue =
                gr.getDisplayValue(
                    "priority"
                );


            var priorityText =
                String(
                    priorityValue
                ).toLowerCase();


            if (
                priorityText.indexOf(
                    "high"
                ) !== -1
            ) {

                item.priority =
                    "High";

            } else if (
                priorityText.indexOf(
                    "medium"
                ) !== -1
            ) {

                item.priority =
                    "Medium";

            } else {

                item.priority =
                    "Low";
            }
        }


        // =================================================
        // SUBMITTED DATE
        // =================================================

        item.submitted_on =
            "";


        if (
            gr.isValidField(
                "sys_created_on"
            )
        ) {

            item.submitted_on =
                gr.getDisplayValue(
                    "sys_created_on"
                );
        }


        // =================================================
        // PUSH CASE
        // =================================================

        data.cases.push(
            item
        );
    }

})();
